begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(17);
insert into employees(id,full_name,position) values('e1000000-0000-4000-8000-000000000001','Invoice owner','owner_admin'),('e1000000-0000-4000-8000-000000000002','Invoice cashier','kasir');
insert into suppliers(id,name) values('e2000000-0000-4000-8000-000000000001','Invoice supplier'),('e2000000-0000-4000-8000-000000000002','Other invoice supplier');
create temporary table inventory_before as select (select count(*) from product_batches) as batches,(select coalesce(sum(quantity),0) from product_batches) as quantity,(select md5(coalesce(string_agg(id::text||coalesce(cost_price::text,'NULL'),',' order by id),'')) from products) as costs,(select md5(coalesce(string_agg(id::text||selling_price::text,',' order by id),'')) from product_units) as prices;
select lives_ok($$select save_purchase_invoice_draft('e3000000-0000-4000-8000-000000000001','e4000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',null,'{"supplier_id":"e2000000-0000-4000-8000-000000000001","invoice_number":" INV-TEST ","invoice_date":"2026-10-29","total_amount":"100.00","paid_amount":"0.00"}')$$,'creates draft');
select is((select status from purchase_invoices where id='e3000000-0000-4000-8000-000000000001'),'draft','status stays draft');
select is((select count(*)::integer from purchase_invoice_payments where invoice_id='e3000000-0000-4000-8000-000000000001'),0,'zero payment creates no fictional payment');
select lives_ok($$select save_purchase_invoice_draft('e3000000-0000-4000-8000-000000000001','e4000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',null,'{"supplier_id":"e2000000-0000-4000-8000-000000000001","invoice_number":" INV-TEST ","invoice_date":"2026-10-29","total_amount":"100.00","paid_amount":"0.00"}')$$,'identical create retry is safe');
select is((select version from purchase_invoices where id='e3000000-0000-4000-8000-000000000001'),1,'retry does not increment version');
select throws_ok($$select save_purchase_invoice_draft('e3000000-0000-4000-8000-000000000002',gen_random_uuid(),'e1000000-0000-4000-8000-000000000001',null,'{"supplier_id":"e2000000-0000-4000-8000-000000000001","invoice_number":"inv-test","invoice_date":"2026-10-29","total_amount":"100.00","paid_amount":"20.00"}')$$,'23505',null,'supplier invoice uniqueness is case-insensitive');
select lives_ok($$select save_purchase_invoice_draft('e3000000-0000-4000-8000-000000000002',gen_random_uuid(),'e1000000-0000-4000-8000-000000000001',null,'{"supplier_id":"e2000000-0000-4000-8000-000000000002","invoice_number":"INV-TEST","invoice_date":"2026-10-29","total_amount":"100.00","paid_amount":"100.00"}')$$,'same invoice number permitted for different supplier');
select lives_ok($$select save_purchase_invoice_draft('e3000000-0000-4000-8000-000000000001',gen_random_uuid(),'e1000000-0000-4000-8000-000000000001',1,'{"supplier_id":"e2000000-0000-4000-8000-000000000001","invoice_number":"INV-EDIT","invoice_date":"2026-10-28","total_amount":"200.00","paid_amount":"50.00"}')$$,'edit creates partial initial payment atomically');
select is((select amount from purchase_invoice_payments where invoice_id='e3000000-0000-4000-8000-000000000001'),50::numeric,'partial payment stored');
select throws_ok($$select save_purchase_invoice_draft('e3000000-0000-4000-8000-000000000001',gen_random_uuid(),'e1000000-0000-4000-8000-000000000001',1,'{}')$$,'P0001','INVOICE_VERSION_CONFLICT','stale edit rejected');
select throws_ok($$select save_purchase_invoice_draft(gen_random_uuid(),gen_random_uuid(),'e1000000-0000-4000-8000-000000000002',null,'{}')$$,'P0001','FORBIDDEN','cashier cannot save');
select throws_ok($$select save_purchase_invoice_draft(gen_random_uuid(),gen_random_uuid(),'e1000000-0000-4000-8000-000000000001',null,'{"supplier_id":"e2000000-0000-4000-8000-000000000001","invoice_number":"BAD","invoice_date":"2026-10-29","total_amount":"100.00","paid_amount":"100.01"}')$$,'P0001','INVALID_PURCHASE_INVOICE','overpayment rejected');
select lives_ok($$select save_purchase_invoice_draft('e3000000-0000-4000-8000-000000000001',gen_random_uuid(),'e1000000-0000-4000-8000-000000000001',2,'{"supplier_id":"e2000000-0000-4000-8000-000000000001","invoice_number":"INV-EDIT","invoice_date":"2026-10-28","total_amount":"200.00","paid_amount":"200.00"}')$$,'edit changes initial payment to fully paid');
select is((select count(*)::integer from purchase_invoice_payments where invoice_id='e3000000-0000-4000-8000-000000000001'),1,'edit never duplicates initial payment');
select ok(not has_table_privilege('authenticated','public.purchase_invoices','INSERT') and not has_function_privilege('authenticated','public.save_purchase_invoice_draft(uuid,uuid,uuid,integer,jsonb)','EXECUTE'),'browser role cannot write invoices directly');
select is((select public from storage.buckets where id='purchase-invoices'),false,'documents bucket is private');
select results_eq($$select (select count(*) from product_batches),(select coalesce(sum(quantity),0) from product_batches),(select md5(coalesce(string_agg(id::text||coalesce(cost_price::text,'NULL'),',' order by id),'')) from products),(select md5(coalesce(string_agg(id::text||selling_price::text,',' order by id),'')) from product_units)$$,$$select * from inventory_before$$,'create and edit leave all stock and prices unchanged');
select * from finish();
rollback;
